Definition tailE (ex : bool) (sg : Z) (de : list Z) : list Z := if ex then 101 :: sg :: de else [].
Definition okE (ex : bool) (sg : Z) (de : list Z) : Prop := ex = true -> (sg = 43 \/ sg = 45) /\ WdGnum.alldig de /\ (2 <= length de)%nat.
Definition hdE (ex : bool) : Z := if ex then 101 else 0.
